@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-2026-001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isSearching">
                @if (isSearching)
                {
                    <span class="spinner-border spinner-border-sm" role="status"></span>
                }
                else
                {
                    <span>Track</span>
                }
            </button>
        </div>
    </div>
</div>

@if (searchPerformed && trackedShipment is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number "<strong>@searchedNumber</strong>".
    </div>
}

@if (trackedShipment is not null)
{
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@trackedShipment.TrackingNumber</h5>
            <span class="badge @GetStatusBadgeClass(trackedShipment.Status) fs-6">
                @trackedShipment.Status
            </span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Description</dt>
                        <dd>@trackedShipment.Description</dd>
                        <dt>Origin</dt>
                        <dd>@trackedShipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@trackedShipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@trackedShipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd class="fs-5 fw-bold text-primary">
                            @trackedShipment.EstimatedDelivery.ToString("MMMM dd, yyyy")
                        </dd>
                    </dl>
                </div>
            </div>

            @{
                var progress = GetDeliveryProgress(trackedShipment);
            }
            <div class="mt-3">
                <label class="form-label">Delivery Progress</label>
                <div class="progress" style="height: 25px;">
                    <div class="progress-bar @GetProgressBarClass(trackedShipment.Status)"
                         role="progressbar"
                         style="width: @(progress)%"
                         aria-valuenow="@progress"
                         aria-valuemin="0"
                         aria-valuemax="100">
                        @(progress)%
                    </div>
                </div>
            </div>
        </div>
    </div>
}

<hr class="my-4" />

<h3>My Shipments</h3>
@if (myShipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!myShipments.Any())
{
    <p>No shipments associated with your account.</p>
}
else
{
    <div class="row">
        @foreach (var shipment in myShipments)
        {
            <div class="col-md-6 mb-3">
                <div class="card @(shipment.Status == ShipmentStatus.Delayed ? "border-warning" : "")">
                    <div class="card-body">
                        <div class="d-flex justify-content-between">
                            <h6 class="card-title">@shipment.TrackingNumber</h6>
                            <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                        </div>
                        <p class="card-text mb-1">@shipment.Description</p>
                        <small class="text-muted">@shipment.Origin → @shipment.Destination</small>
                        <p class="mt-2 mb-0">
                            <strong>ETA:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")
                        </p>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private bool searchPerformed;
    private bool isSearching;
    private ShipmentDto? trackedShipment;
    private List<ShipmentDto>? myShipments;

    [CascadingParameter]
    private Task<AuthenticationState>? AuthState { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (AuthState is not null)
        {
            var state = await AuthState;
            var email = state.User.Identity?.Name ?? "";
            myShipments = await ShipmentService.GetShipmentsForCustomerAsync(email);
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        isSearching = true;
        searchedNumber = trackingNumber.Trim();
        trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searchPerformed = true;
        isSearching = false;
    }

    private static int GetDeliveryProgress(ShipmentDto shipment) => shipment.Status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 85,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 40,
        _ => 0
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delayed => "bg-warning",
        ShipmentStatus.Delivered => "bg-success",
        _ => ""
    };
}
